    playlist_details[pl_id] = detail
    print(f"Playlist {pl_id} ({detail['title']}):")
    for song in detail.get('songs', []):
        print(f"  Song ID: {song['id']}, Title: {song['title']}")

# Identify songs to archive from all playlists
old_titles_set = set(old_song_titles)
songs_to_remove = []  # list of (playlist_id, song_id, title)
unique_song_ids = set()

for pl_id, detail in playlist_details.items():
    for song in detail.get('songs', []):
        if song['title'] in old_titles_set:
            songs_to_remove.append((pl_id, song['id'], song['title']))
            unique_song_ids.add(song['id'])

print("Songs to remove (playlist_id, song_id, title):")
for item in songs_to_remove:
    print(item)
print("Unique song IDs to add:", unique_song_ids)

