steps.code:
# Search for each archived song in Spotify to get its song_id
archived_song_ids = []
for song in archive_songs:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, access_token=spotify_login['access_token'], page_limit=20)
    # Find exact match
    found = None
    for r in results:
        if r['title'].lower() == song['title'].lower():
            # Check artist match
            artist_names = [a['name'].lower() for a in r['artists']]
            if song['artist'].lower() in artist_names:
                found = r
                break
    if found:
        archived_song_ids.append(found['song_id'])
        print(f"Found: {song['title']} by {song['artist']} -> ID {found['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']} by {song['artist']}")

print(f"\nTotal archived song IDs found: {len(archived_song_ids)}")

