# Let's search for each song in the archive list to get their song_ids
archive_song_ids = []
for song in songs_to_archive:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(query=query, access_token=spotify_token, page_index=0, page_limit=20)
    # Find the matching song
    found = None
    for s in results:
        if s['title'].lower() == song['title'].lower():
            # Check if artist matches
            artist_names = [a['name'].lower() for a in s['artists']]
            if song['artist'].lower() in artist_names:
                found = s
                break
    if found:
        archive_song_ids.append(found['song_id'])
        print(f"Found: {song['title']} by {song['artist']} -> song_id={found['song_id']}")
