steps.code:
# We have all 13 target song IDs. Let's compute which playlists contain them.
target_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}

# Build a mapping: playlist_id -> list of target song_ids present
removals = {}
for pl in playlists:
    pl_id = pl['playlist_id']
    present = [sid for sid in pl['song_ids'] if sid in target_song_ids]
    if present:
        removals[pl_id] = present

print("Removals mapping:", removals)

# Collect all unique song IDs to be archived
all_removed_song_ids = set()
for song_ids in removals.values():
    all_removed_song_ids.update(song_ids)
print("Unique songs to archive:", all_removed_song_ids)

